import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·23","description":"易小帖 - 卷四·23","frontmatter":{"title":"卷四·23","description":"易小帖 - 卷四·23"},"headers":[],"relativePath":"zh/classics/yixiaotie/117.md","filePath":"zh/classics/yixiaotie/117.md"}'),o={name:"zh/classics/yixiaotie/117.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·23",tabindex:"-1"},[r("卷四·23 "),e("a",{class:"header-anchor",href:"#卷四·23","aria-label":"Permalink to “卷四·23”"},"​")],-1),e("p",null,"西南得朋，陰與陰行，故不如東北喪朋之有慶，此最易明者。朱氏謂：喪朋之有慶，仍當轉而西南，則何如直曰「西南得朋，乃終有慶」之為明快乎。且西南未必有慶也。何玄子引《參同契》雲：「雄不獨處，雌不孤居。」以明牝牡意當相須。假使二女共守，顔色甚姝。蘇秦通言，張儀合媒，推心調諧，合為夫妻，敝髮腐齒終不相知，此正西南得朋類行無慶之証。朱氏親註《參同契》而不知此理，吾不解也。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
